#### 2. Infrastructure Anti-Corruption Adapter & Mapping Functions

```typescript
// src/infrastructure/carriers/fedex/fedex-mapper.ts
import type { ShippingRate } from "../../../domain/shipping/types.js";
import type { FedExRateReplyDetail } from "./fedex-sdk-types.js";

export function mapFedExRateToDomain(detail: FedExRateReplyDetail): ShippingRate {
  return {
    carrierId: "fedex",
    serviceName: detail.serviceType,
    totalCost: {
      amount: detail.ratedShipmentDetails[0].totalNetCharge.amount,
      currency: detail.ratedShipmentDetails[0].totalNetCharge.currency,
    },
    estimatedDays: detail.operationalDetail.transitDays ?? 3,
  };
}
```

```typescript
// src/infrastructure/carriers/fedex/fedex-adapter.ts
import type { ShippingCarrierPort } from "../../../domain/shipping/carrier-port.js";
import type { CarrierError, RateQuoteRequest, Result, ShippingRate } from "../../../domain/shipping/types.js";
import type { FedExClient } from "./fedex-client.js";
import { mapFedExRateToDomain } from "./fedex-mapper.js";

export class FedExAdapter implements ShippingCarrierPort {
  public readonly carrierId = "fedex";

  public constructor(private readonly client: FedExClient) {}

  public async getRates(req: RateQuoteRequest): Promise<Result<ShippingRate[], CarrierError>> {
    try {
      const response = await this.client.fetchRates(req);
      const rates = response.rateReplyDetails.map(mapFedExRateToDomain);
      return { ok: true, value: rates };
    } catch (err) {
      return { ok: false, error: this.mapError(err) };
    }
  }

  private mapError(err: unknown): CarrierError {
    return {
      kind: "ProviderError",
      carrier: this.carrierId,
      code: "FEDEX_API_ERROR",
      message: err instanceof Error ? err.message : String(err),
    };
  }
}
```

#### 3. Strategy Dispatcher

```typescript
// src/application/carrier-registry.ts
import type { ShippingCarrierPort } from "../domain/shipping/carrier-port.js";

export class CarrierStrategyRegistry {
  private readonly carriers = new Map<string, ShippingCarrierPort>();

  public register(carrier: ShippingCarrierPort): void {
    this.carriers.set(carrier.carrierId, carrier);
  }

  public get(carrierId: string): ShippingCarrierPort {
    const carrier = this.carriers.get(carrierId);
    if (!carrier) {
      throw new Error(`Carrier '${carrierId}' is not registered.`);
    }
    return carrier;
  }
}
```

