```typescript
import { describe, expect, it, vi } from "vitest";
import { RegisterUserUseCase } from "../src/application/register-user.use-case.js";
import { DomainEvent, OutboxRepository, UnitOfWork, User, UserRepository } from "../src/domain/user.js";

describe("Transactional Outbox Contract Verification", () => {
  it("rolls back outbox entry when user repository save fails", async () => {
    const mockUserRepo: UserRepository = {
      save: vi.fn().mockRejectedValue(new Error("Database constraint violation")),
    };
    const mockOutboxRepo: OutboxRepository = {
      append: vi.fn().mockResolvedValue(undefined),
    };
    const mockUow: UnitOfWork = {
      execute: async (work) => work(null),
    };

    const useCase = new RegisterUserUseCase(mockUserRepo, mockOutboxRepo, mockUow);

    await expect(useCase.execute({ id: "user-1", email: "test@example.com" }))
      .rejects.toThrow("Database constraint violation");

    expect(mockUserRepo.save).toHaveBeenCalledOnce();
    // Verify outbox was never persisted outside transaction
  });
});
```

