#### B. Anti-Corruption Adapters (`src/infrastructure/carriers/`)

```typescript
// src/infrastructure/carriers/fedex/fedex.adapter.ts
import { ShippingCarrierPort, LabelRequest, ShippingQuote, ShippingLabel } from '../../../domain/carrier';
// Vendor SDK isolated strictly to infrastructure layer
import { FedExClient, FedExRateRequestDTO } from '@fedex/sdk'; 

export class FedExCarrierAdapter implements ShippingCarrierPort {
  readonly carrierId = 'FEDEX';

  constructor(private readonly fedexClient: FedExClient) {}

  async getRates(request: LabelRequest): Promise<ShippingQuote[]> {
