#### C. Carrier Registry / Service Resolver

```typescript
// src/infrastructure/carriers/carrier.registry.ts
import { ShippingCarrierPort } from '../../domain/carrier/carrier.port';

export class CarrierRegistry {
  private adapters = new Map<string, ShippingCarrierPort>();

